syntax:
namespace <namespace_name> {
    // declarations
}

// Accessing a name within a namespace
<namespace_name>::<name>

// Using directive to bring all names into current scope
using namespace <namespace_name>;

// Using declaration to bring specific name into scope
using <namespace_name>::<name>;

code_example:
#include <iostream>

namespace math {
    int add(int a, int b) { return a + b; }
}

int main() {
    // Accessing function via namespace scope resolution
    std::cout << "Sum: " << math::add(3, 4) << std::endl;
    // Using directive to simplify access
    using namespace math;
    std::cout << "Sum with using: " << add(5, 6) << std::endl;
    return 0;
}
